insert into public.podcasts(id,title,summary,body,subject,audio_url,audio_seconds,is_sample,status,published_at) values
('d8761234-a456-4ab6-8e0d-000000000001','برنامه هفتگی که واقعاً اجرا می‌شود','چطور یک برنامه قابل‌انعطاف بسازیم؛ با کارهای کوچک، زمان جبران و مرور کوتاه پایان روز.','{"type": "doc", "content": [{"type": "image", "attrs": {"src": "https://raw.githubusercontent.com/esi-khafan1/nova/6ad3055579eb53da9844c1dac9726934baeb9030/public/podcasts/covers/planning.svg", "alt": "تصویرسازی اختصاصی پادکست نووا درباره برنامه‌ریزی"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "متن همراه پادکست"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "سلام. به پادکست نووا خوش آمدید. این قسمت نمونه با صدای مصنوعی تهیه شده است. امروز درباره برنامه ریزی هفتگی واقع بینانه حرف می زنیم."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "یک برنامه خوب، قرار نیست تمام خانه های تقویم را پر کند. قرار است به تو کمک کند قدم بعدی را روشن ببینی. اول، زمان های ثابت هفته را بنویس. مدرسه، رفت و آمد، خواب و استراحت. فقط زمان باقی مانده برای مطالعه آزاد است."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "بعد، سه اولویت انتخاب کن. مثلاً مرور یک فصل ریاضی، حل چند تست زیست و جمع بندی درس ادبیات. هر اولویت را به یک کار کوچک و قابل انجام تبدیل کن. به جای نوشتنِ ریاضی بخوانم، بنویس پنج مسئله از مبحث مشخص حل کنم و پاسخ ها را بررسی کنم."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "برای هر روز کمی زمان خالی بگذار. اگر یک کار عقب افتاد، این زمان به تو فرصت جبران می دهد. برنامه بدون جای خالی، با اولین اتفاق غیرمنتظره به هم می ریزد."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "آخر هر شب، فقط سه چیز را مرور کن. چه کاری انجام شد؟ چه کاری بیشتر از انتظار زمان برد؟ فردا چه تغییری لازم است؟ این مرور، قضاوت درباره ارزش تو نیست؛ فقط اطلاعاتی برای بهتر کردن برنامه است."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "برای شروع، همین امروز یک بازه کوتاه انتخاب کن و یک کار مشخص را انجام بده. برنامه ای که اجرا می شود، از برنامه بی نقص روی کاغذ ارزشمندتر است. تا قسمت بعد، مراقب انرژی و زمانت باش."}]}]}','برنامه‌ریزی','/podcasts/audio/planning',99,true,'published',now()),
('d8761234-a456-4ab6-8e0d-000000000002','تمرکز را با یک قدم کوچک برگردان','کم‌کردن حواس‌پرتی، انتخاب یک کار روشن و شروع یک بازه کوتاه مطالعه؛ بدون سرزنش خودمان.','{"type": "doc", "content": [{"type": "image", "attrs": {"src": "https://raw.githubusercontent.com/esi-khafan1/nova/6ad3055579eb53da9844c1dac9726934baeb9030/public/podcasts/covers/focus.svg", "alt": "تصویرسازی اختصاصی پادکست نووا درباره تمرکز"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "متن همراه پادکست"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "سلام. این پادکست نمونه نووا با صدای مصنوعی آماده شده است. امروز قرار است درباره برگشتن به تمرکز صحبت کنیم؛ بدون سرزنش خودمان و بدون انتظار تمرکز بی وقفه."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "قبل از شروع مطالعه، یک کار مشخص انتخاب کن. مثلاً خواندن دو صفحه و توضیح دادن نکته اصلی با زبان خودت. وقتی مقصد کوچک و روشن باشد، شروع کردن آسان تر می شود."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "گوشی را ساکت کن و کمی دورتر از میز بگذار. اگر برای درس به آن نیاز داری، فقط ابزار لازم را باز نگه دار. لازم نیست همیشه همه چیز را حذف کنی؛ کافی است حواس پرتی را برای همین بازه کوتاه کمتر کنی."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "یک بازه قابل تحمل انتخاب کن. برای بعضی ها پانزده دقیقه مناسب است و برای بعضی ها بیست و پنج دقیقه. این عدد قانون همگانی نیست. هدف این است که بتوانی تا پایان بازه، روی همان کار بمانی."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "اگر فکری وسط مطالعه آمد، یک کلمه درباره آن روی کاغذ بنویس و به درس برگرد. لازم نیست همان لحظه به هر فکر پاسخ بدهی. بعد از بازه، چند دقیقه استراحت کن. کمی راه برو، آب بنوش و چشم ها را از صفحه دور کن."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "در پایان، از خودت بپرس چه چیزی به تمرکزم کمک کرد؟ به جای گفتنِ من همیشه حواس پرتم، یک تغییر کوچک برای نوبت بعد پیدا کن. اگر دشواری تمرکز ادامه دار است و زندگی روزانه را مختل می کند، با فرد متخصص گفت و گو کن. این پادکست تشخیص یا درمان نیست. قدم بعدی تو می تواند فقط یک بازه آرام و کوتاه باشد."}]}]}','تمرکز','/podcasts/audio/focus',103,true,'published',now()),
('d8761234-a456-4ab6-8e0d-000000000003','بعد از آزمون، خودت را قضاوت نکن','اشتباه‌ها را به سه گروه تقسیم کن و فقط دو اقدام مشخص برای هفته بعد انتخاب کن.','{"type": "doc", "content": [{"type": "image", "attrs": {"src": "https://raw.githubusercontent.com/esi-khafan1/nova/6ad3055579eb53da9844c1dac9726934baeb9030/public/podcasts/covers/review.svg", "alt": "تصویرسازی اختصاصی پادکست نووا درباره تحلیل آزمون"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "متن همراه پادکست"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "سلام. به یک قسمت دیگر از پادکست نووا خوش آمدید. این قسمت آموزشی نمونه، با صدای مصنوعی تهیه شده است. موضوع امروز، تحلیل آزمون بدون سرزنش خودمان است."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "بعد از آزمون، لازم نیست فوراً سراغ رتبه و مقایسه بروی. کمی استراحت کن و بعد پاسخ هایت را با آرامش بررسی کن. هدف تحلیل، پیدا کردن کار بعدی است، نه برچسب زدن به خودت."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "سوال های اشتباه و نزده را در سه گروه قرار بده. گروه اول، سوال هایی که مطلبشان را نمی دانستی. برای این گروه، بخش کوتاهی از درس را مرور کن و بعد یک سوال مشابه حل کن."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "گروه دوم، سوال هایی که راه حل را می دانستی اما در محاسبه یا خواندن صورت سوال اشتباه کردی. برای این گروه، یک یادآور کوتاه بنویس؛ مثلاً قبل از انتخاب گزینه، خواسته سوال را دوباره بخوانم."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "گروه سوم، سوال هایی که زمان کافی برایشان نداشتی. بررسی کن کجا بیشتر از حد لازم متوقف شدی و دفعه بعد چه سوالی را می توانی برای دور دوم بگذاری."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "حالا از میان همه نکته ها، فقط دو اقدام برای هفته بعد انتخاب کن. تعداد کمِ اقدام روشن، از یک فهرست طولانی و مبهم کاربردی تر است. نتیجه یک آزمون، تمام توانایی تو را تعریف نمی کند. از آن اطلاعات بگیر و برنامه ات را کمی بهتر کن."}]}, {"type": "paragraph", "content": [{"type": "text", "text": "برای شروع، یک سوال اشتباه را انتخاب کن، دلیلش را بنویس و یک سوال مشابه را با دقت حل کن. همین تمرین کوچک، شروع خوبی برای ادامه مسیر است."}]}]}','تحلیل آزمون','/podcasts/audio/review',100,true,'published',now())
